<script>
 import {pages} from './windows11-settings.js';
 let {native,execute,profile}=$props();const state=$derived(native.apps.settings);const quick=$derived(native.shell.quick);
 const accountName=$derived(profile.defaults.accountName);
 const accountInitials=$derived(accountName.split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase());
 const names={home:'Home',system:'System',display:'Display',sound:'Sound',network:'Network & internet',personalization:'Personalization',background:'Background',colors:'Colors',about:'About'};
 const nav=page=>execute({command:'win11.settings.navigate',target:{page},payload:{}});
 const send=(name,payload={},target={})=>execute({command:`win11.settings.${name}`,target,payload});
 const pref=(control,value)=>send('preference',{value},{control});
 const setQuick=(control,value)=>execute({command:'win11.quick.set',target:{control},payload:{value}});
 const wallpapers=['bloom','glow','flow'];const accents=['#0078d4','#8764b8','#107c10','#d83b01'];
 const results=$derived(pages.filter(page=>names[page].toLowerCase().includes(state.search.toLowerCase())));
</script>
{#snippet link(page,description,icon)}<button class="card link" data-control={`settings-link-${page}`} onclick={()=>nav(page)}><span class="icon">{icon}</span><span><strong>{names[page]}</strong><small>{description}</small></span><span>›</span></button>{/snippet}
{#snippet toggle(control,label,detail='')}<label class="card"><span><strong>{label}</strong>{#if detail}<small>{detail}</small>{/if}</span><span class="toggle"><span>{state[control]?'On':'Off'}</span><input type="checkbox" data-control={`settings-${control}`} checked={state[control]} onchange={event=>pref(control,event.currentTarget.checked)} /></span></label>{/snippet}
<section class="settings" style={`--settings-accent:${state.accent}`} class:dark={state.theme==='dark'}><div class="settings-layout" inert={state.ui.dialog!==null}><aside class="w11-app-sidebar"><div class="account"><span class="avatar">{accountInitials}</span><div><strong>{accountName}</strong><small>Local account</small></div></div><input class="search" data-control="settings-search" placeholder="Find a setting" aria-label="Find a setting" value={state.search} oninput={event=>send('search',{value:event.currentTarget.value})} /><nav>{#each ['home','system','network','personalization'] as page}<button data-control={`settings-nav-${page}`} class:selected={state.page===page||(page==='system'&&['display','sound','about'].includes(state.page))||(page==='personalization'&&['background','colors'].includes(state.page))} onclick={()=>nav(page)}>{page==='home'?'⌂':page==='system'?'▣':page==='network'?'◎':'✎'}　{names[page]}</button>{/each}</nav><p class="sidebar-note">Other Settings categories are not represented in this offline scene.</p></aside>
 <main data-area="settings-content" onscroll={event=>execute({command:'win11.apps.scroll.observe',target:{appId:'settings',area:'settings-content'},payload:{top:event.currentTarget.scrollTop,left:event.currentTarget.scrollLeft}})}><header><h1>{#if ['display','sound','about'].includes(state.page)}<button data-control="settings-system-breadcrumb" onclick={()=>nav('system')}>System</button>　›　{:else if ['background','colors'].includes(state.page)}<button data-control="settings-personalization-breadcrumb" onclick={()=>nav('personalization')}>Personalization</button>　›　{/if}{names[state.page]}</h1><button data-control="settings-options" aria-label="Settings options" onclick={()=>execute({command:'win11.apps.menu',target:{appId:'settings'},payload:{menu:state.ui.menu?null:'options'}})}>···</button></header>
 {#if state.ui.menu}<div class="w11-app-menu"><p>Preferences are fictional and retained for this scene only.</p><button data-control="settings-menu-about" onclick={()=>nav('about')}>About Windows</button><button data-control="settings-menu-close" onclick={()=>execute({command:'win11.apps.menu',target:{appId:'settings'},payload:{menu:null}})}>Close menu</button></div>{/if}
 {#if state.search}<h2>Search results</h2>{#each results as page}{@render link(page,'Open represented Settings page','⌕')}{:else}<p>No represented settings match “{state.search}”.</p>{/each}
 {:else if state.page==='home'}<div class="device"><div class="monitor">▦</div><div><h2>{state.deviceName}</h2><small>Fictional studio workstation</small><button class="text-button" data-control="settings-home-rename" onclick={()=>send('dialog',{dialog:'rename'})}>Rename</button></div><div class="connection"><strong>{quick.wifi&&!quick.airplane?'Studio Wi-Fi':'Not connected'}</strong><small>Fictional network</small></div></div><div class="home-grid"><section class="group"><h2>Recommended settings</h2>{@render link('display','Brightness, night light, display scale','☀')}{@render link('sound','Volume, output, mono audio','♫')}{@render link('network','Wi-Fi and network preferences','◎')}</section><section class="group"><h2>Personalization</h2><div class="wallpapers">{#each wallpapers as wallpaper}<button class={`wallpaper ${wallpaper}`} class:chosen={state.wallpaper===wallpaper} data-control={`settings-home-wallpaper-${wallpaper}`} aria-label={`${wallpaper} background`} onclick={()=>pref('wallpaper',wallpaper)}></button>{/each}</div><label class="card"><strong>Color mode</strong><select data-control="settings-home-theme" value={state.theme} onchange={event=>pref('theme',event.currentTarget.value)}><option value="light">Light</option><option value="dark">Dark</option></select></label>{@render link('personalization','Background, colors and effects','✎')}</section></div><p class="footnote">Local account: cloud storage, subscriptions and account recovery are not connected.</p>
 {:else if state.page==='system'}<div class="device"><div class="monitor">▦</div><div><h2>{state.deviceName}</h2><small>Local fictional PC</small></div></div>{@render link('display','Brightness, night light, scale, display resolution','☀')}{@render link('sound','Volume levels, output, sound preferences','♫')}{@render link('about','Device specifications, Windows specifications','ⓘ')}<p class="footnote">Power, storage management and real hardware operations are not represented.</p>
 {:else if state.page==='display'}<div class="display-preview">1</div><h2>Brightness & color</h2><label class="card"><span><strong>Brightness</strong><small>Fictional display brightness · {quick.brightness}%</small></span><input type="range" data-control="settings-brightness" min="0" max="100" value={quick.brightness} oninput={event=>setQuick('brightness',Number(event.currentTarget.value))} /></label>{@render toggle('nightLight','Night light','Store a warmer-color preference for this scene')}<h2>Scale & layout</h2><label class="card"><span><strong>Scale</strong><small>Fictional display preference, does not resize the host screen</small></span><select data-control="settings-scale" value={state.scale} onchange={event=>pref('scale',Number(event.currentTarget.value))}>{#each [100,125,150,175] as scale}<option value={scale}>{scale}%</option>{/each}</select></label><label class="card"><strong>Display resolution</strong><select data-control="settings-resolution" value={state.resolution} onchange={event=>pref('resolution',event.currentTarget.value)}>{#each ['1920 × 1080','1600 × 900','1280 × 720'] as resolution}<option>{resolution}</option>{/each}</select></label>
 {:else if state.page==='sound'}<h2>Output</h2><label class="card"><span><strong>Choose where to play sound</strong><small>Fictional audio devices; no host audio</small></span><select data-control="settings-output" value={state.output} onchange={event=>pref('output',event.currentTarget.value)}><option>Speakers</option><option>Headphones</option></select></label><label class="card"><strong>Volume · {quick.volume}%</strong><input data-control="settings-volume" type="range" min="0" max="100" value={quick.volume} oninput={event=>setQuick('volume',Number(event.currentTarget.value))} /></label>{@render toggle('monoAudio','Mono audio','Combine left and right channels preference')}{@render toggle('notificationSounds','Notification sounds','Fictional preference only; no audio playback')}
 {:else if state.page==='network'}<div class="network-summary"><span>◎</span><div><h2>{quick.wifi&&!quick.airplane?'Studio Wi-Fi':'Not connected'}</h2><p>{quick.wifi&&!quick.airplane?'Connected to a fictional network':'Fictional wireless connection is off'}</p></div></div>{#each [['wifi','Wi-Fi'],['airplane','Airplane mode'],['bluetooth','Bluetooth']] as [control,label]}<label class="card"><strong>{label}</strong><span class="toggle"><span>{quick[control]?'On':'Off'}</span><input data-control={`settings-quick-${control}`} type="checkbox" checked={quick[control]} onchange={event=>setQuick(control,event.currentTarget.checked)} /></span></label>{/each}<label class="card"><strong>Network profile type</strong><select data-control="settings-network-profile" value={state.networkProfile} onchange={event=>pref('networkProfile',event.currentTarget.value)}><option>Private</option><option>Public</option></select></label>{@render toggle('metered','Metered connection','Store a data-use preference for the fictional network')}<button class="card link" data-control="settings-network-properties" onclick={()=>send('dialog',{dialog:'network'})}><strong>Hardware properties</strong><span>›</span></button>
 {:else if ['personalization','background','colors'].includes(state.page)}<div class={`appearance-preview ${state.wallpaper}`}><div class:preview-dark={state.theme==='dark'}><div style={`background:${state.accent}`}></div><span>Windows</span><span class="preview-bar"></span></div></div>{#if state.page==='personalization'}{@render link('background','Background image','▧')}{@render link('colors','Color mode, accent, transparency','◉')}{@render toggle('animation','Animation effects','Fictional motion preference')}{:else if state.page==='background'}<h2>Personalize your background</h2><div class="wallpapers">{#each wallpapers as wallpaper}<button class={`wallpaper ${wallpaper}`} class:chosen={state.wallpaper===wallpaper} data-control={`settings-wallpaper-${wallpaper}`} onclick={()=>pref('wallpaper',wallpaper)}><span>{wallpaper}</span></button>{/each}</div><p class="footnote">Locally authored scene wallpapers; no online Spotlight or host files.</p>{:else}<label class="card"><strong>Choose your mode</strong><select data-control="settings-theme" value={state.theme} onchange={event=>pref('theme',event.currentTarget.value)}><option value="light">Light</option><option value="dark">Dark</option></select></label><h2>Accent color</h2><div class="accents">{#each accents as accent}<button style={`background:${accent}`} class:chosen={state.accent===accent} data-control={`settings-accent-${accent.slice(1)}`} aria-label={`Accent ${accent}`} onclick={()=>pref('accent',accent)}>{state.accent===accent?'✓':''}</button>{/each}</div>{@render toggle('transparency','Transparency effects','Fictional visual preference')}{/if}
 {:else if state.page==='about'}<div class="device"><div class="monitor">▦</div><div><h2>{state.deviceName}</h2><small>Fictional workstation</small></div><button data-control="settings-about-rename" onclick={()=>send('dialog',{dialog:'rename'})}>Rename this PC</button></div><section class="group"><h2>Device specifications</h2><dl><dt>Device name</dt><dd>{state.deviceName}</dd><dt>Processor</dt><dd>Fictional studio CPU</dd><dt>Installed RAM</dt><dd>16.0 GB (fictional)</dd><dt>System type</dt><dd>64-bit operating system, x64-based processor</dd><dt>Pen and touch</dt><dd>No pen or touch input is available for this display</dd></dl></section><section class="group"><h2>Windows specifications</h2><dl><dt>Edition</dt><dd>Windows 11 Pro</dd><dt>Version</dt><dd>23H2</dd><dt>Installed on</dt><dd>10/31/2023 (scene)</dd><dt>OS build</dt><dd>22631.2428</dd></dl></section><p class="footnote">JesterOS native screen-prop simulation. Specifications describe the fictional scene, not this computer.</p>{/if}
 {#if state.message}<p class="saved" role="status">{state.message}</p>{/if}</main></div>
 {#if state.ui.dialog}<div class="scrim" role="dialog" aria-modal="true" aria-label={state.ui.dialog==='rename'?'Rename your PC':'Network properties'}><section class="w11-app-dialog">{#if state.ui.dialog==='rename'}<h2>Rename your PC</h2><p>Use 1–15 letters, digits or hyphens, including a letter. This changes only the fictional device name.</p><input data-control="settings-rename-input" aria-label="Device name" value={state.draftName} oninput={event=>send('renameDraft',{value:event.currentTarget.value})} /><div class="dialog-actions"><button class="primary" data-control="settings-rename-save" onclick={()=>send('renameSave')}>Save</button><button data-control="settings-rename-cancel" onclick={()=>send('dialog',{dialog:'none'})}>Cancel</button></div>{:else}<h2>Studio Wi-Fi properties</h2><dl><dt>SSID</dt><dd>Studio Wi-Fi</dd><dt>Protocol</dt><dd>Wi-Fi 6 (fictional)</dd><dt>IPv4 address</dt><dd>192.0.2.41 (documentation-only)</dd><dt>Profile</dt><dd>{state.networkProfile}</dd><dt>Metered</dt><dd>{state.metered?'Yes':'No'}</dd></dl><p>No real network discovery or connection occurs.</p><button data-control="settings-network-close" onclick={()=>send('dialog',{dialog:'none'})}>Close</button>{/if}</section></div>{/if}
</section>
<style>
 .settings{height:100%;position:relative;background:var(--w11-theme-surface,#f9f9f9);color:var(--w11-theme-text,#242424)}.settings-layout{height:100%;display:flex}.settings.dark{background:#202020;color:#eee}.settings aside{width:230px;flex-shrink:0;padding:22px 14px;background:var(--w11-theme-chrome,#f1f1f1)}.dark aside{background:#292929}.account{display:flex;align-items:center;gap:12px;margin-bottom:24px}.avatar{border-radius:50%;width:46px;height:46px;display:grid;place-items:center;background:#d6e6f8;color:#324b66}.account small,small{display:block;font-size:12px;opacity:.68;margin-top:4px}.search{width:100%;padding:9px;border:1px solid var(--w11-theme-border,#aaa);border-bottom:2px solid var(--w11-theme-border,#777);background:var(--w11-theme-card,white);border-radius:5px;margin-bottom:20px}.settings nav button{display:block;width:100%;text-align:left;background:transparent;border:0;padding:12px 8px;margin:3px 0}.settings nav .selected{border-left:3px solid var(--settings-accent);background:#e3e3e3}.dark nav .selected{background:#383838}.settings button{cursor:pointer;border:1px solid var(--w11-theme-border,#ddd);background:var(--w11-theme-card,#fff);border-radius:5px;padding:8px 13px;color:inherit}.settings button:hover{filter:brightness(.96)}.dark button,.dark .card,.dark .group{background:#2b2b2b;border-color:#444}.sidebar-note,.footnote{font-size:12px;opacity:.65;line-height:1.6;margin-top:25px}.settings main{flex:1;min-width:0;padding:28px;overflow:auto}.settings header{display:flex;gap:8px;justify-content:space-between;align-items:start;margin-bottom:20px}h1{font-size:27px;font-weight:600;margin:0}h1 button{padding:0!important;border:0!important;background:transparent!important;color:var(--w11-theme-muted,#666)!important;font-size:24px;font-weight:600}h2{font-size:17px;font-weight:600;margin:20px 0 14px}.card{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid var(--w11-theme-border,#e6e6e6);background:var(--w11-theme-card,#fff);border-radius:5px;padding:18px;margin:5px 0;min-height:65px}.settings button.card{width:100%;text-align:left;padding:18px}.card strong{font-size:14px;font-weight:500}.link>span:nth-child(2){flex:1}.icon{width:25px;font-size:21px}.device{display:flex;gap:20px;align-items:center;margin:24px 0 30px}.device h2{margin:0;font-size:21px}.device>button,.connection{margin-left:auto}.connection{text-align:right}.monitor{font-size:42px;color:#52769c}.settings .text-button{border:0;background:transparent;color:var(--settings-accent);padding:4px 0}.home-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.group{border:1px solid var(--w11-theme-border,#e2e2e2);border-radius:8px;background:var(--w11-theme-card,white);padding:18px;margin:12px 0}.group>h2{margin-top:0}.group .card{border:0;padding:10px 0!important}.wallpapers{display:flex;gap:9px;margin:15px 0}.settings .wallpaper{flex:1;min-height:85px;border:2px solid transparent;position:relative}.wallpaper span{position:absolute;bottom:5px;left:8px;color:white;text-transform:capitalize;font-size:12px}.bloom{background:radial-gradient(ellipse at 70% 70%,#2078f1 0%,#0b3cab 25%,transparent 26%),radial-gradient(ellipse at 40% 30%,#4c9df7,#111d66)!important}.glow{background:radial-gradient(ellipse at 50% 80%,#ffb790,#754386 40%,#222941)!important}.flow{background:linear-gradient(135deg,#a9ede5,#007a8b 45%,#064961)!important}.settings .chosen{outline:2px solid var(--settings-accent);outline-offset:2px}.appearance-preview{height:180px;width:290px;border-radius:8px;margin:20px 0 25px;display:grid;place-items:center}.appearance-preview>div{width:150px;height:95px;background:#fff;border-radius:5px;box-shadow:0 3px 15px #0005;position:relative;padding:22px;font-size:13px}.appearance-preview>div>div{width:25px;height:25px;border-radius:4px;float:left;margin-right:7px}.appearance-preview .preview-dark{background:#252525;color:white}.preview-bar{position:absolute;bottom:0;left:0;right:0;height:12px;background:#bbb8}.accents{display:flex;gap:10px;margin:20px 0}.accents button{width:42px;height:42px;color:white;font-size:22px}.toggle{display:flex;align-items:center;gap:10px;font-size:12px}.toggle input{accent-color:var(--settings-accent);width:19px;height:19px}.settings select{background:var(--w11-theme-card,white);border:1px solid var(--w11-theme-border,#bbb);border-radius:5px;padding:7px;max-width:190px}.settings input[type=range]{accent-color:var(--settings-accent);max-width:200px;width:40%}.display-preview{width:190px;height:110px;display:grid;place-items:center;background:var(--w11-accent);color:white;border:5px solid var(--w11-theme-border,#666);border-radius:5px;font-size:32px;margin:20px auto 28px}.network-summary{display:flex;gap:20px;align-items:center;margin:25px 0}.network-summary>span{font-size:50px;color:var(--settings-accent)}.network-summary h2{margin:0}dl{display:grid;grid-template-columns:145px 1fr;gap:12px;font-size:13px}dt{font-weight:500}dd{margin:0;overflow-wrap:anywhere}.saved{font-size:12px;color:var(--settings-accent);margin-top:24px}.scrim{position:absolute;inset:0;background:#0005;display:grid;place-items:center;padding:15px;z-index:10}.scrim section{background:var(--w11-theme-chrome,#fafafa);color:var(--w11-theme-text,#222);max-width:410px;padding:26px;border-radius:8px;box-shadow:0 8px 35px #0005}.scrim h2{margin-top:0}.scrim p{font-size:13px;line-height:1.5}.scrim input{width:100%;padding:10px;border:1px solid var(--w11-theme-border,#999);border-radius:4px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.settings .primary{background:var(--settings-accent);color:white;border-color:transparent}@media(max-width:720px){.settings aside{width:170px;padding:15px 8px}.settings main{padding:18px}.home-grid{grid-template-columns:1fr}.connection{display:none}h1{font-size:24px}h1 button{font-size:20px}.card{gap:9px;padding:12px}.settings select{max-width:145px}dl{grid-template-columns:110px 1fr}}@media(max-width:470px){.settings aside{width:125px}.account{gap:5px}.avatar{display:none}.account strong{font-size:12px}.settings nav button{font-size:12px;padding:10px 4px}.settings main{padding:12px}.appearance-preview{width:100%}.card{flex-wrap:wrap}.device{gap:8px}.monitor{font-size:30px}dl{grid-template-columns:1fr;gap:5px}dd{margin-bottom:10px}}
 .dark .scrim section{background:#202020;color:#eee}
</style>
